<script setup>
import {ref} from 'vue';
const props=defineProps({event:Object,participant:Object});const emit=defineEmits(['updated']);
const rating=ref(props.participant.rating||''),feedback=ref(props.participant.feedback||''),busy=ref(false),error=ref(''),notice=ref('');
async function save(){busy.value=true;error.value='';notice.value='';try{const {data}=await window.axios.post('/api/student/events/'+props.event.id+'/feedback',{rating:rating.value,feedback:feedback.value});emit('updated',data.participant);notice.value='Avaliação salva. Obrigado por participar!';}catch(e){error.value=Object.values(e.response?.data?.errors||{}).flat()[0]||e.response?.data?.message||'Não foi possível salvar.';}finally{busy.value=false;}}
</script>
<template><section class="student-card event-feedback"><h2>{{event.modules.feedback.title}}</h2><p>{{event.modules.feedback.message}}</p><p v-if="!event.finished">A pesquisa será liberada após o encerramento pela equipe.</p><p v-else-if="!participant.checkedInAt">Confirme sua presença com a equipe para avaliar.</p><form v-else @submit.prevent="save"><fieldset><legend>Sua nota</legend><div class="rating-stars"><label v-for="n in 5" :key="n"><input v-model="rating" type="radio" :value="n" :name="'rating-'+event.id" required /><span>{{n}} ★</span></label></div></fieldset><label>Comentário (opcional)<textarea v-model="feedback" maxlength="1000" rows="3" /></label><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><button class="btn-primary" :disabled="busy">{{participant.rating?'Atualizar avaliação':'Enviar avaliação'}}</button></form></section></template>
<style scoped>.event-feedback{padding:24px!important;margin-top:20px}.event-feedback h2{font-size:24px;font-weight:750}.event-feedback p{margin:12px 0;line-height:1.7}.event-feedback textarea{width:100%;border:1px solid var(--wn-line);border-radius:12px;padding:12px;font-size:16px}.event-feedback label{display:grid;gap:8px;margin:16px 0}.rating-stars{display:flex;gap:8px;flex-wrap:wrap}.rating-stars label{position:relative;margin:12px 0}.rating-stars input{position:absolute;opacity:0;inset:0}.rating-stars span{display:block;padding:12px;border:1px solid var(--wn-line);border-radius:10px;cursor:pointer}.rating-stars input:checked+span{background:var(--wn-primary);font-weight:700}.rating-stars input:focus-visible+span{outline:2px solid var(--wn-ink);outline-offset:3px}</style>
